#!/usr/bin/env python3
"""Read-only sorry census + import-reachability for a Lean project."""
import os, re, sys, json

ROOT_DIR = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
ROOT_MODULE = "AlgebraicJacobian"

def lean_files(base):
    out = []
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d != ".lake" and not d.startswith(".git")]
        for fn in filenames:
            if fn.endswith(".lean"):
                out.append(os.path.join(dirpath, fn))
    return sorted(out)

def strip_comments(text):
    """Replace Lean comments with spaces (preserving newlines/offsets).
    Handles nested /- -/ (including /-- -/ docstrings), -- line comments,
    and skips string literals and char literals so `--` inside a string is safe."""
    out = list(text)
    i, n = 0, len(text)
    depth = 0
    while i < n:
        c = text[i]
        if depth > 0:
            if text.startswith("/-", i):
                depth += 1
                out[i] = out[i+1] = " "
                i += 2
                continue
            if text.startswith("-/", i):
                depth -= 1
                out[i] = out[i+1] = " "
                i += 2
                continue
            if c != "\n":
                out[i] = " "
            i += 1
            continue
        # depth == 0
        if text.startswith("/-", i):
            depth = 1
            out[i] = out[i+1] = " "
            i += 2
            continue
        if text.startswith("--", i):
            j = i
            while j < n and text[j] != "\n":
                out[j] = " "
                j += 1
            i = j
            continue
        if c == '"':
            # string literal
            out[i] = " "
            i += 1
            while i < n:
                if text[i] == "\\":
                    out[i] = " "
                    if i+1 < n and text[i+1] != "\n":
                        out[i+1] = " "
                    i += 2
                    continue
                if text[i] == '"':
                    out[i] = " "
                    i += 1
                    break
                if text[i] != "\n":
                    out[i] = " "
                i += 1
            continue
        i += 1
    return "".join(out)

TOKEN = re.compile(r"(?<![A-Za-z0-9_'!?])sorry(?![A-Za-z0-9_'!?])")

files = lean_files(ROOT_DIR)

# module name <-> path
def mod_of_path(p):
    rel = os.path.relpath(p, ROOT_DIR)
    assert rel.endswith(".lean")
    return rel[:-5].replace(os.sep, ".")

path_of_mod = {mod_of_path(p): p for p in files}

IMPORT = re.compile(r"^\s*import\s+(?:all\s+)?([A-Za-z_][A-Za-z0-9_.'À-￿]*)", re.M)

imports = {}
sorries = {}
for p in files:
    raw = open(p, encoding="utf-8", errors="replace").read()
    stripped = strip_comments(raw)
    hits = []
    for m in TOKEN.finditer(stripped):
        line = stripped.count("\n", 0, m.start()) + 1
        hits.append(line)
    if hits:
        sorries[p] = hits
    imports[mod_of_path(p)] = IMPORT.findall(stripped)

# transitive closure from root
seen = set()
stack = [ROOT_MODULE]
missing_root = ROOT_MODULE not in path_of_mod
while stack:
    m = stack.pop()
    if m in seen:
        continue
    seen.add(m)
    for dep in imports.get(m, []):
        if dep in path_of_mod and dep not in seen:
            stack.append(dep)

rooted_paths = {path_of_mod[m] for m in seen if m in path_of_mod}

print("ROOT MODULE:", ROOT_MODULE, "->", path_of_mod.get(ROOT_MODULE), "MISSING" if missing_root else "")
print("total project .lean files:", len(files))
print("files reachable from root (incl. root):", len(rooted_paths))
print()
total = 0
rows = []
for p in sorted(sorries):
    cnt = len(sorries[p])
    total += cnt
    rows.append((p, cnt, "ROOTED" if p in rooted_paths else "UNROOTED", sorries[p]))
for p, cnt, st, lines in rows:
    print(f"{p} | {cnt} | {st} | lines: {','.join(map(str,lines))}")
print()
print("TOTAL code sorries:", total, "in", len(rows), "files")
print("ROOTED files:", sum(1 for r in rows if r[2]=='ROOTED'), "sorries:", sum(r[1] for r in rows if r[2]=='ROOTED'))
print("UNROOTED files:", sum(1 for r in rows if r[2]=='UNROOTED'), "sorries:", sum(r[1] for r in rows if r[2]=='UNROOTED'))

